import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    return len(get_divisors(n))

def solve_search(N_max):
    results = []
    print(f"Starting search up to N = {N_max}")

    for n in range(1, N_max + 1):
        if tau(n) >= 5:
            divisors = get_divisors(n)

            # Since tau(n) >= 5, we are guaranteed to have at least 5 divisors.
            # Divisors are 1, d2, d3, d4, d5, ...
            # a is the second smallest (index 1)
            # b is the third smallest (index 2)
            # c is the fifth smallest (index 4)

            a = divisors[1]
            b = divisors[2]
            c = divisors[4]

            # Check the condition n = ab + ac + bc
            check_value = a * b + a * c + b * c

            if check_value == n:
                results.append({
                    'n': n,
                    'tau(n)': tau(n),
                    'a': a,
                    'b': b,
                    'c': c,
                    'check': True
                })

    return results

# Perform the search up to N=200 for a slightly more robust initial check
search_limit = 200
successful_n = solve_search(search_limit)

print("\n--- Search Results ---")
if successful_n:
    print("Successful values of n found:")
    for res in successful_n:
        print(f"n = {res['n']}, tau(n) = {res['tau(n)']}, a={res['a']}, b={res['b']}, c={res['c']}")
else:
    print("No values of n found up to the search limit.")

